#!/usr/bin/env python3
"""Experimental full firmware boot with cache candidate; no checkpoint reuse."""
import hashlib,json,subprocess,sys
from pathlib import Path
root=Path.cwd();out=root/'build/sim/runs/flash-all-equal-probe';out.mkdir(parents=True,exist_ok=True)
rtl=root/'scratch/variant-origin-quiet-zap/src/rtl';board=root/'scratch/flash-all-equal-probe';obj=root/'build/sim/obj-flash-all-equal-probe';binary=obj/'Vngage_cpu_sim'
rom=root/'build/firmware/digest-probes/both/SYM.ROM';extension=root/'build/firmware/nem4-extension/extension.bin'
inputs=[*sorted(rtl.glob('*.sv')),*sorted(rtl.glob('*.svh')),root/'rtl/ngage_cpu.sv',root/'scratch/checkpoint-probe/ngage_cpu_sim.sv',board/'main.cpp',board/'boot_profile.cpp',board/'boot_profile.h',rom,extension,Path(__file__).resolve()]
sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest();inputs_hash={str(p.relative_to(root)):sha(p) for p in inputs}
cmd=['docker','run','--rm','--network','none','--platform','linux/arm64','-v',str(root)+':/work','-w','/work','--entrypoint','verilator','jotego/simulator:arm64','--cc','--exe','--build','-j','4','--savable','--assert','-DNGAGE_RUNTIME_TRACE','-Wno-fatal','-Wno-lint','--x-initial','0','--x-assign','0','--top-module','ngage_cpu_sim','--Mdir',str(obj.relative_to(root)),'-I'+str(rtl.relative_to(root)),'rtl/ngage_cpu.sv','scratch/checkpoint-probe/ngage_cpu_sim.sv',*[str(p.relative_to(root)) for p in sorted(rtl.glob('*.sv'))],'/work/scratch/flash-all-equal-probe/main.cpp','/work/scratch/flash-all-equal-probe/boot_profile.cpp']
with (out/'build.log').open('w') as f:r=subprocess.run(cmd,stdout=f,stderr=subprocess.STDOUT)
if r.returncode:raise SystemExit('Build failed; see build.log')
for cache in obj.rglob('*.gch'): cache.unlink()
if any(sha(root/p)!=h for p,h in inputs_hash.items()):raise SystemExit('Inputs changed during build')
cv=lambda p:'/work/'+str(p.relative_to(root));scenario={'warning':'EXPERIMENTAL cache-disabled table-origin RTL and provisional devices, NOT validated hardware or authentic firmware','source_hashes':inputs_hash,'binary_sha256':sha(binary),'max_cycles':50000,'memory_latency':0,'checkpoint_restored':False,'cache_forced_off':True,'assumptions':['derived firmware digest','synthetic all-equal 227e flash identities and table 638; no extension','ideal clocks','LCD transport','timer IRQ delay 18200000','UEM ADC6=512','UEM power/status','CBUS write/read assumptions','GPIO and system-control probes','GPIO206 exact writes 0x180/0x6 without side effects','GPIO214 low reset assumed zero','PUP F004 low and F006 high reset assumed zero']}
(out/'provenance.json').write_text(json.dumps(scenario,indent=2)+'\n');(out/'result.json').write_text('')
cmd=['docker','run','--rm','--network','none','--platform','linux/arm64','-v',str(root)+':/work','-w','/work','--entrypoint',cv(binary),'jotego/simulator:arm64',cv(rom),'50000','0',*[cv(out/f) for f in ('instructions.tsv','bus.tsv','cp15.tsv','result.json')],'amd16','ideal-clocks','lcd-probe','boot-io-probe','+ngage-compact-trace','uem-adc=6=512','timer-irq-delay=18200000','uem-power-status=0','uem-status36=0','uem-status35=16','cbus-write-allow=0x27','cbus-write-allow2=0x82','cbus82-readback','cbus80-input=0x400','cbus8d-zero','icu46-write','pupf00a-zero','sysc0c14-zero','probe-register=0x0c120c10:0:15','probe-register=0x0c120c0c:0:15','probe-register=0x0c14f000:0:3','probe-register=0x0c14f004:0:12','probe-register=0x0c150204:0:12','uif-write-8000','icu-write-25','gpio210-low-zero','gpio21a-zero','gpio216-zero','gpio214-low-zero','pupf004-low-zero','gpio206-extra-write','uif102-write']
print('Counterfactual all-equal flash IDs, cache disabled',flush=True)
# Retain targeted table writes and at most 64 KiB of other diagnostics.
with (out/'simulator.log').open('w') as f:
 p=subprocess.Popen(cmd,stdout=subprocess.PIPE,stderr=subprocess.STDOUT,text=True,errors='replace')
 kept=omitted=0
 for line in p.stdout:
  marker=line.find('VARIANT_TABLE_WRITE')
  if marker>=0: f.write(line[marker:]);f.flush()
  elif kept < 65536: f.write(line[:65536-kept]);kept+=len(line)
  else: omitted+=len(line)
 rc=p.wait();f.write(f'\n[Other diagnostic bytes omitted: {omitted}]\n')
class Result: pass
r=Result();r.returncode=rc

if not (out/'result.json').stat().st_size:raise SystemExit(f'No result, simulator exit {r.returncode}; inspect simulator.log')
if any(sha(root/p)!=h for p,h in inputs_hash.items()) or sha(binary)!=scenario['binary_sha256']:raise SystemExit('Inputs changed while simulation ran; do not use result')
x=json.loads((out/'result.json').read_text());print('RESULT',x['status'],x['cycles'],hex(x['blocked_address']),x.get('blocked_reason',''),flush=True)
print('No LCD capture generated by the table-origin run.',flush=True)
